    repo_root: &Path,
    target_dir: &Path,
    path: &str,
    bins: &[&str],
    features: &[&str],
    force: bool,
) -> String {
    std::iter::once("cargo".to_string())
        .chain(install_args(repo_root, target_dir, path, bins, features, force))
        .collect::<Vec<_>>()
        .join(" ")
}

