### 6. **MCP Server Initialization**

**File:** [workflow-tools/ticket/src/server.rs](workflow-tools/ticket/src/server.rs#L48-L199)

```rust
#[derive(Clone)]
pub struct TicketServer {
    index_root: PathBuf,
    tool_router: ToolRouter<Self>,
    store_lock: Arc<Mutex<()>>,
}

pub fn open_canonical_store(
    index_root: &Path,
) -> Result<TicketStore, ticket_api::error::StorageError> {
    let store = TicketStore::open(index_root)?;  // ← Errors if not initialized
    let workspace_root = ticket_api::workspace::resolve_workspace_root_from_store_root(
        &store.index_root,
        ticket_api::workspace::TICKET_INDEX_DIR,
    );
    store.reapply_workspace_policy(&workspace_root)?;
    Ok(store)
}

impl TicketServer {
    pub fn new(index_root: PathBuf) -> Self {
        Self {
            index_root,
            tool_router: Self::tool_router(),
            store_lock: Arc::new(Mutex::new(())),
        }
    }

    async fn with_store<T>(
        &self,
        workspace: &str,
        f: impl FnOnce(&TicketStore) -> Result<T, ticket_api::error::StorageError>,
    ) -> Result<T, McpError> {
        let index_root = self.resolve_workspace_root(workspace)?;
        let _guard = self.store_lock.lock().await;
        let store = TicketStore::open(&index_root).map_err(Self::store_err)?;  // ← Errors if not initialized
        store.scan(false).map_err(Self::store_err)?;
        let result = f(&store).map_err(Self::store_err);
        drop(store);
        result
    }

    fn store_err(error: ticket_api::error::StorageError) -> McpError {
        McpError::internal_error(format!("store error: {error}"), None)
    }
}
```

**Behavior:** 
- Uses `TicketStore::open()` — does NOT call `open_or_init()`
- Errors with `WorkspaceNotFound` are converted to `McpError::internal_error()`
- **No automatic initialization** — requires `ticket init` to have been run first

arguments.content:
//! Shared "open, or initialize on first use" pattern for index-rooted
//! stores. Every domain (ticket, spec, rule, ...) defines its own store
//! type and error, so this only centralizes the retry-on-missing-workspace
//! branching; each domain still supplies its own `open`/`init` closures.

/// Implemented by a domain's error type so [`open_or_init`] can tell "no
/// store exists yet at this path" apart from any other failure.
pub trait NotFoundError {
    fn is_workspace_not_found(&self) -> bool;
}

/// Try `open`; if it fails because the workspace hasn't been created yet,
/// fall back to `init`. Any other error from `open`, or any error from
/// `init`, propagates unchanged.
pub fn open_or_init<S, E>(
    open: impl FnOnce() -> Result<S, E>,
    init: impl FnOnce() -> Result<S, E>,
) -> Result<S, E>
where
    E: NotFoundError,
{
    match open() {
        Ok(store) => Ok(store),
        Err(error) if error.is_workspace_not_found() => init(),
        Err(error) => Err(error),
    }
}

