        report
            .scan_reports
            .insert("post_init_scan".to_string(), initial_scan);
    }
    report.phase_timings_ms.insert(
        "open_or_init_total_ms".to_string(),
        elapsed_ms(overall_started),
    );
    emit_store_open_report("ticket_store_open_or_init_complete", &report);
